import{_ as r,C as s,o as t,c as n,a2 as o,b as d,w as a,a as c,E as l,a3 as h}from"./chunks/framework.ChIlRNAd.js";const v=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"en/technical/security.md","filePath":"en/technical/security.md"}'),u={name:"en/technical/security.md"};function p(b,e,m,g,k,f){const i=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>Overview of the security measures implemented in Nid.</p><hr><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><h3 id="httponly-jwt" tabindex="-1">httpOnly JWT <a class="header-anchor" href="#httponly-jwt" aria-label="Permalink to &quot;httpOnly JWT&quot;">​</a></h3><p>The JWT (HS256) is stored in the <strong>httpOnly cookie</strong> <code>token</code>, inaccessible to client-side JavaScript. This protects against XSS attacks that would attempt to steal the token.</p><ul><li><strong>Single token</strong>: lifetime <code>JWT_EXPIRY</code> (24 h by default), same as the cookie</li><li><strong>Cookie</strong>: <code>httpOnly</code>, <code>sameSite: strict</code>, <code>secure</code> in production</li><li><code>POST /api/auth/refresh</code> re-issues a token for a still-valid session; the frontend does not call it automatically</li><li>The frontend stores no token (neither in <code>localStorage</code> nor in URLs: SSE streams use the cookie too)</li></ul><h3 id="redis-jwt-blacklist" tabindex="-1">Redis JWT Blacklist <a class="header-anchor" href="#redis-jwt-blacklist" aria-label="Permalink to &quot;Redis JWT Blacklist&quot;">​</a></h3><p>On logout, the token is added to a Redis blacklist. The <code>authenticate</code> middleware checks this blacklist on every request, enabling <strong>immediate invalidation</strong> of a compromised token. It also rejects (401) a disabled user (<code>users.is_active = false</code>).</p><h3 id="password-hashing" tabindex="-1">Password Hashing <a class="header-anchor" href="#password-hashing" aria-label="Permalink to &quot;Password Hashing&quot;">​</a></h3><p>Passwords are hashed with <strong>bcrypt</strong> (12 rounds). A dummy hash is computed even when the user doesn&#39;t exist, which prevents account enumeration through timing attacks.</p><h3 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Route</th><th>Limit</th></tr></thead><tbody><tr><td><code>POST /api/auth/register</code></td><td>3 requests / minute</td></tr><tr><td><code>POST /api/auth/login</code></td><td>5 requests / minute</td></tr><tr><td>General routes</td><td>100 requests / minute / IP</td></tr></tbody></table><h3 id="_2fa-totp" tabindex="-1">2FA TOTP <a class="header-anchor" href="#_2fa-totp" aria-label="Permalink to &quot;2FA TOTP&quot;">​</a></h3><p>Two-factor authentication is optional for local accounts. It uses <strong>TOTP</strong> (RFC 6238) via <code>otplib</code>, with QR code generation for setup.</p><h3 id="passkeys-webauthn" tabindex="-1">Passkeys (WebAuthn) <a class="header-anchor" href="#passkeys-webauthn" aria-label="Permalink to &quot;Passkeys (WebAuthn)&quot;">​</a></h3><p>Passwordless sign-in through <code>@simplewebauthn/server</code>, bound to the frontend&#39;s site (<code>FRONTEND_URL</code>). User verification (the device&#39;s PIN or biometrics) is required, so the passkey is two factors on its own: the TOTP 2FA is not asked again. Only the public key is stored; challenges are single-use (Redis, 5 min). See <a href="./api/auth.html#passkeys-webauthn">API › Passkeys</a>.</p><h3 id="multi-provider-sso" tabindex="-1">Multi-Provider SSO <a class="header-anchor" href="#multi-provider-sso" aria-label="Permalink to &quot;Multi-Provider SSO&quot;">​</a></h3><p>Social Login uses the <strong>Arctic</strong> library with server-side OAuth2 code exchange. Social tokens never transit through the frontend.</p><p>Supported providers: Google, Microsoft, Discord, Facebook, LinkedIn, Keycloak (providers without configured credentials are disabled). The <code>state</code> and the PKCE code verifier are kept 5 min in Redis. Only a provider-verified email may be linked to an existing account or match <code>ADMIN_EMAIL</code>.</p><h3 id="gmail-tokens" tabindex="-1">Gmail Tokens <a class="header-anchor" href="#gmail-tokens" aria-label="Permalink to &quot;Gmail Tokens&quot;">​</a></h3><p>Gmail OAuth2 tokens (<code>access_token</code>, <code>refresh_token</code>) are stored <strong>in plain text</strong> in <code>mail_accounts</code>: protection relies on database access. When an account is disconnected, they are set to <code>NULL</code>.</p><hr><h2 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h2><h3 id="multi-user-isolation" tabindex="-1">Multi-User Isolation <a class="header-anchor" href="#multi-user-isolation" aria-label="Permalink to &quot;Multi-User Isolation&quot;">​</a></h3><p>Two Fastify decorators ensure data isolation:</p><ul><li><strong><code>requireAccountOwnership</code></strong> — Verifies that the <code>:accountId</code> parameter belongs to the authenticated user. Applied on all Gmail, archive, dashboard, and rules routes.</li><li><strong><code>requireAdmin</code></strong> — Verifies that <code>role === &#39;admin&#39;</code> in the JWT. Applied on admin and integrity routes, and on the archive trash configuration.</li></ul><p>Routes combine them through <code>authPresets(app)</code> (<code>auth</code>, <code>accountAuth</code>, <code>adminAuth</code>). Routes without <code>:accountId</code> (jobs, notifications, retention policies…) filter on <code>user_id = request.user.sub</code>.</p>',28)),(t(),d(h,null,{default:a(()=>[l(i,{id:"mermaid-143",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20REQ%5BHTTP%20request%5D%20--%3E%20AUTH%5Bauthenticate%5D%0A%20%20%20%20AUTH%20--%3E%20OWN%7BrequireAccountOwnership%7D%0A%20%20%20%20OWN%20--%3E%7COK%7C%20HANDLER%5BHandler%20route%5D%0A%20%20%20%20OWN%20--%3E%7C403%7C%20REJECT%5BAcc%C3%A8s%20refus%C3%A9%5D%0A%20%20%20%20%0A%20%20%20%20AUTH%20--%3E%20ADM%7BrequireAdmin%7D%0A%20%20%20%20ADM%20--%3E%7COK%7C%20ADMIN_HANDLER%5BHandler%20admin%5D%0A%20%20%20%20ADM%20--%3E%7C403%7C%20REJECT%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Access</th></tr></thead><tbody><tr><td><code>user</code></td><td>Own data (emails, archives, rules, jobs, notifications)</td></tr><tr><td><code>admin</code></td><td>Same + administration page (users, global jobs, quotas, integrity)</td></tr></tbody></table><hr><h2 id="input-validation" tabindex="-1">Input Validation <a class="header-anchor" href="#input-validation" aria-label="Permalink to &quot;Input Validation&quot;">​</a></h2><p>All user inputs are validated with <strong>Zod</strong>:</p><ul><li>Strict schemas on request bodies, query params, and URL parameters</li><li>TypeScript types inferred from Zod schemas</li><li>Unknown fields are ignored (Zod&#39;s default behavior); a validation error returns <code>400 { error, details }</code></li></ul><p>Full-text search uses <code>plainto_tsquery</code> (not <code>to_tsquery</code>), which neutralizes query operators and protects against PostgreSQL operator injection.</p><hr><h2 id="archive-encryption" tabindex="-1">Archive Encryption <a class="header-anchor" href="#archive-encryption" aria-label="Permalink to &quot;Archive Encryption&quot;">​</a></h2><p>EML archives can be encrypted at rest on the NAS:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Value</th></tr></thead><tbody><tr><td>Algorithm</td><td>AES-256-GCM (confidentiality + integrity)</td></tr><tr><td>Key derivation</td><td>PBKDF2 (SHA-512, 100,000 iterations)</td></tr><tr><td>Salt</td><td>32 random bytes per file</td></tr><tr><td>IV</td><td>12 random bytes per file</td></tr><tr><td>Passphrase storage</td><td>Scrypt hash in database — never the passphrase itself</td></tr></tbody></table><h3 id="binary-format" tabindex="-1">Binary Format <a class="header-anchor" href="#binary-format" aria-label="Permalink to &quot;Binary Format&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GMENC01 (7 B) | SALT (32 B) | IV (12 B) | AUTH_TAG (16 B) | CIPHERTEXT</span></span></code></pre></div><ul><li>Magic bytes <code>GMENC01</code> for encrypted file detection</li><li>On-the-fly decryption without temporary files</li><li>Idempotency: already encrypted files are skipped</li></ul><hr><h2 id="network-security" tabindex="-1">Network Security <a class="header-anchor" href="#network-security" aria-label="Permalink to &quot;Network Security&quot;">​</a></h2><h3 id="production" tabindex="-1">Production <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Production&quot;">​</a></h3><ul><li>The <code>nid</code> container only exposes port 3000 (Nginx), configurable through <code>APP_PORT</code></li><li>CORS configured for <code>FRONTEND_URL</code> only</li></ul><div class="warning custom-block"><p class="custom-block-title">PostgreSQL and Redis exposed by default</p><p>The provided <code>docker-compose.yml</code> publishes <code>5432</code> (PostgreSQL) and <code>6379</code> (Redis) on the host, for dev tools. Remove these <code>ports:</code> blocks in production if these services must not be reachable outside the <code>nid-net</code> Docker network.</p></div><h3 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h3><p>Webhooks of type <code>generic</code> include an <code>X-Webhook-Signature</code> header (<code>sha256=&lt;HMAC-SHA256 of the payload&gt;</code>), allowing the recipient to verify the request&#39;s authenticity. Optional Basic authentication is available (<code>auth_user</code>, <code>auth_password</code>).</p><p>SSRF protection: URLs resolving to a loopback, private, link-local (cloud metadata), CGNAT or unspecified address are refused, unless <code>WEBHOOK_ALLOW_PRIVATE_NETWORKS=true</code> (ntfy, Home Assistant on the LAN…).</p><h3 id="email-content" tabindex="-1">Email Content <a class="header-anchor" href="#email-content" aria-label="Permalink to &quot;Email Content&quot;">​</a></h3><p>Remote images in emails are blocked by default in the reader (<code>notification_preferences.remote_images = &#39;block&#39;</code>), which defeats tracking pixels.</p><hr><h2 id="file-security" tabindex="-1">File Security <a class="header-anchor" href="#file-security" aria-label="Permalink to &quot;File Security&quot;">​</a></h2><ul><li>Filenames in <code>Content-Disposition</code> headers are sanitized</li><li>File paths are validated to prevent directory traversal</li><li>EML files are identified by UUID, not by user-provided paths</li><li>Archive share links (<code>/shared/:token</code>) use a unique random token, with an expiry date and an optional maximum access count; expired links are cleaned up hourly</li></ul><h2 id="secrets-in-jobs" tabindex="-1">Secrets in Jobs <a class="header-anchor" href="#secrets-in-jobs" aria-label="Permalink to &quot;Secrets in Jobs&quot;">​</a></h2><p>Credentials passed to a job (encryption passphrase, IMAP password) are stripped from the payload copy stored in the <code>jobs</code> table (readable through <code>/api/jobs</code> and admin). In Redis, such jobs are removed as soon as they end; they cannot be replayed through <code>POST /api/jobs/:jobId/retry</code>.</p><hr><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>All sensitive actions are tracked in the audit log:</p><table tabindex="0"><thead><tr><th>Category</th><th>Tracked Actions</th></tr></thead><tbody><tr><td>Authentication</td><td>Login (password, Google SSO, social), registration, 2FA enable / disable</td></tr><tr><td>Gmail accounts</td><td>Account connection, disconnection</td></tr><tr><td>Rules</td><td>Creation (including from a template), modification, deletion, execution</td></tr><tr><td>Bulk operations</td><td>Trash, deletion, archiving, labels; deleting a sender&#39;s mails</td></tr><tr><td>Archives</td><td>Archive run, ZIP export</td></tr><tr><td>Administration</td><td>User modification, archive trash emptying</td></tr></tbody></table><p>Each entry includes the request&#39;s IP address for traceability.</p><hr><h2 id="docker-container-security" tabindex="-1">Docker Container Security <a class="header-anchor" href="#docker-container-security" aria-label="Permalink to &quot;Docker Container Security&quot;">​</a></h2><h3 id="base-images" tabindex="-1">Base Images <a class="header-anchor" href="#base-images" aria-label="Permalink to &quot;Base Images&quot;">​</a></h3><ul><li><strong>Alpine images</strong> — Systematic use of Alpine variants to reduce the attack surface (fewer binaries, fewer potential CVEs)</li><li><strong>Updates</strong> — <code>apk upgrade --no-cache</code> in production to apply security patches</li></ul><h3 id="multi-stage-build" tabindex="-1">Multi-Stage Build <a class="header-anchor" href="#multi-stage-build" aria-label="Permalink to &quot;Multi-Stage Build&quot;">​</a></h3><p>The root <code>Dockerfile</code> (unified nginx + Node image) uses a <strong>multi-stage build</strong> (frontend-builder, backend-builder → deps → runner) so the final image contains:</p><ul><li>No source code</li><li>No devDependencies</li><li>No build tools (npm, corepack, yarn)</li></ul><h3 id="non-root-user" tabindex="-1">Non-Root User <a class="header-anchor" href="#non-root-user" aria-label="Permalink to &quot;Non-Root User&quot;">​</a></h3><p>Processes run as a <strong>non-root user</strong> (<code>appuser:appgroup</code>, UID/GID 1001): <code>entrypoint.sh</code> starts as root to fix volume permissions, then switches through <code>su-exec</code>. Code and nginx config are owned by root (read-only for <code>appuser</code>); only <code>/archives</code> is writable. This limits the impact of a potential compromise of the Node.js process.</p><h3 id="dockerignore" tabindex="-1"><code>.dockerignore</code> <a class="header-anchor" href="#dockerignore" aria-label="Permalink to &quot;`.dockerignore`&quot;">​</a></h3><p><code>.dockerignore</code> files prevent copying sensitive files into the build context:</p><ul><li><code>.env</code>, <code>.env.*</code>, <code>*.pem</code>, <code>*.key</code> — Environment variables and secrets</li><li><code>.git</code> — Git history</li><li><code>node_modules</code>, <code>coverage</code>, <code>dist</code> — Build artifacts</li><li><code>volumes/</code> — User data</li></ul><h3 id="internal-network" tabindex="-1">Internal Network <a class="header-anchor" href="#internal-network" aria-label="Permalink to &quot;Internal Network&quot;">​</a></h3><p>Services talk over the <code>nid-net</code> Docker network. Containers run with <code>no-new-privileges</code> and <code>cap_drop: ALL</code> (only the required capabilities are added back). See the warning above about the PostgreSQL and Redis ports published by default.</p><h3 id="ignore-scripts" tabindex="-1"><code>--ignore-scripts</code> <a class="header-anchor" href="#ignore-scripts" aria-label="Permalink to &quot;`--ignore-scripts`&quot;">​</a></h3><p>Production <code>npm ci</code> commands use <code>--ignore-scripts</code> to prevent execution of potentially malicious <code>postinstall</code> scripts in dependencies.</p>',50))])}const A=r(u,[["render",p]]);export{v as __pageData,A as default};
